    <script>
        const checkboxes = document.querySelectorAll('.cart-checkbox'); const selectedItemsContainer = document.getElementById('selected-items'); const totalPriceEl = document.getElementById('total-price'); const checkoutBtn = document.getElementById('checkout-btn'); let selectedItems = []; let totalPrice = 0;
        checkboxes.forEach(checkbox => { checkbox.addEventListener('change', function () { const itemId = this.dataset.id; const productCard = this.closest('.flex'); const image = productCard.querySelector('img'); const photo = image ? image.getAttribute('src') : null; const name = productCard.querySelector('h3').innerText; const priceText = productCard.querySelector('.text-green-600').innerText; const price = parseInt(priceText.replace(/[^\d]/g, '')); const qty = parseInt(productCard.querySelector('input[name="quantity"]').value); if (this.checked) { selectedItems.push({ id: itemId, name, price, qty, photo }); totalPrice += price * qty; } else { selectedItems = selectedItems.filter(i => i.id !== itemId); totalPrice -= price * qty; } renderSelectedItems(); }); });
        const cartIdsContainer = document.getElementById('cart-ids-container'); function renderSelectedItems() { selectedItemsContainer.innerHTML = ''; cartIdsContainer.innerHTML = ''; selectedItems.forEach(item => { const el = document.createElement('div'); el.classList.add('flex', 'justify-between', 'items-center', 'gap-2', 'text-sm'); el.innerHTML = `<p>${item.qty}x</p>${item.photo ? `<img src="${item.photo}" alt="${item.name}" class="w-12 h-12 object-cover rounded-xl">` : '<div class="w-12 h-12 rounded bg-gray-200 flex items-center justify-center text-xs text-gray-500">No Image</div>'}<p class="flex-1">${item.name}</p><span>Rp ${item.price.toLocaleString()}</span>`; selectedItemsContainer.appendChild(el); const input = document.createElement('input'); input.type = 'hidden'; input.name = 'cart_ids[]'; input.value = item.id; cartIdsContainer.appendChild(input); }); totalPriceEl.innerText = 'Rp ' + totalPrice.toLocaleString(); checkoutBtn.disabled = selectedItems.length === 0; }
    </script>
    <script>function updateQuantity(itemId, change, maxQuantity = 99) { const input = document.getElementById(`quantity-input-${itemId}`); let currentQuantity = parseInt(input.value); if (isNaN(currentQuantity)) currentQuantity = 1; const newQuantity = currentQuantity + change; if (newQuantity <= 0) { document.getElementById(`delete-form-${itemId}`).submit(); return; } if (newQuantity > maxQuantity) return; input.value = newQuantity; const form = document.getElementById(`quantity-form-${itemId}`); const formData = new FormData(form); fetch(form.action, { method: 'POST', headers: { 'X-CSRF-TOKEN': form.querySelector('input[name="_token"]').value, 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json' }, body: formData }).then(response => { if (!response.ok) { console.error('Update gagal'); } }).catch(error => { console.error('Error:', error); }); }</script>
